// Code node "Build alert" (mode: Run Once for All Items).
// Reads the CoinGecko /derivatives response (one item, full response mode), keeps liquid
// perpetual contracts whose funding rate is beyond the threshold, groups them by coin and
// builds one Telegram message.

// Telegram is sent with parse mode HTML: neutralise the only three special characters.
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const cfg = $('Set alert settings').first().json;

const toNumber = (value, name, { min, integer = false }) => {
  const n = value === '' || value === null || value === undefined ? NaN : Number(value);
  if (!Number.isFinite(n) || n < min || (integer && !Number.isInteger(n))) {
    throw new Error(`Config: "${name}" must be ${integer ? 'an integer' : 'a number'} ≥ ${min} (got "${value}")`);
  }
  return n;
};
const thresholdPct = toNumber(cfg.threshold_pct, 'threshold_pct', { min: 0 });
const minVolume = toNumber(cfg.min_volume_24h_usd, 'min_volume_24h_usd', { min: 0 });
const topN = toNumber(cfg.top_n, 'top_n', { min: 1, integer: true });
const onlyNew = cfg.only_new_coins === true || cfg.only_new_coins === 'true';
const exchanges = String(cfg.exchanges || '')
  .split(',')
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);

const contracts = $('Fetch funding rates from CoinGecko').first().json.body;
if (!Array.isArray(contracts)) {
  throw new Error(`CoinGecko did not return a contract list: ${JSON.stringify(contracts).slice(0, 300)}`);
}

// Liquid perpetuals with a usable rate. CoinGecko already returns funding_rate as a percentage.
const liquid = [];
for (const c of contracts) {
  if (!c || c.contract_type !== 'perpetual') continue;
  const ratePct = Number(c.funding_rate);
  const volume = Number(c.volume_24h) || 0;
  if (c.funding_rate === null || !Number.isFinite(ratePct) || volume < minVolume) continue;
  liquid.push({
    coin: String(c.index_id || c.symbol).toUpperCase(),
    market: String(c.market || ''),
    ratePct,
    volume,
  });
}

// Some venues report rates in the wrong unit (e.g. ETH at 1% per funding while every other
// venue shows ~0.003%).
// - Venues with enough contracts are judged on their typical |rate| vs the cross-venue norm.
// - Small venues cannot be judged that way (one genuinely hot coin would flag the whole venue),
//   so each of their contracts is compared with the same coin on the other venues instead.
const median = (a) => {
  if (!a.length) return 0;
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const OUTLIER_FACTOR = 10;
const MIN_CONTRACTS_TO_JUDGE_VENUE = 5;

const byMarket = {};
for (const r of liquid) (byMarket[r.market] = byMarket[r.market] || []).push(r);
const marketMedians = Object.fromEntries(
  Object.entries(byMarket).map(([m, list]) => [m, median(list.map((r) => Math.abs(r.ratePct)))]),
);
const norm = median(Object.values(marketMedians));

const outlierVenues = new Set(
  Object.entries(marketMedians)
    .filter(([m, med]) => byMarket[m].length >= MIN_CONTRACTS_TO_JUDGE_VENUE && norm > 0 && med > norm * OUTLIER_FACTOR)
    .map(([m]) => m),
);

const ratesByCoin = {};
for (const r of liquid) {
  if (outlierVenues.has(r.market)) continue;
  (ratesByCoin[r.coin] = ratesByCoin[r.coin] || []).push(r);
}
const isSuspicious = (r) => {
  if (byMarket[r.market].length >= MIN_CONTRACTS_TO_JUDGE_VENUE) return false;
  const others = (ratesByCoin[r.coin] || []).filter((o) => o.market !== r.market).map((o) => o.ratePct);
  if (others.length < 3) return false; // nothing to compare with: keep it
  const reference = Math.max(Math.abs(median(others)), norm);
  return Math.abs(r.ratePct) > reference * OUTLIER_FACTOR;
};

const hits = liquid.filter((r) => {
  if (outlierVenues.has(r.market) || isSuspicious(r)) return false;
  if (Math.abs(r.ratePct) < thresholdPct) return false;
  if (exchanges.length && !exchanges.some((e) => r.market.toLowerCase().includes(e))) return false;
  return true;
});

// One entry per coin: how many venues, rate range, and the most liquid venue.
const byCoin = {};
for (const r of hits) (byCoin[r.coin] = byCoin[r.coin] || []).push(r);
const coins = Object.entries(byCoin).map(([coin, list]) => {
  const rates = list.map((r) => r.ratePct);
  const min = Math.min(...rates);
  const max = Math.max(...rates);
  const top = list.reduce((a, b) => (b.volume > a.volume ? b : a));
  return { coin, venues: list.length, min, max, extreme: Math.abs(min) > Math.abs(max) ? min : max, top };
});
coins.sort((a, b) => Math.abs(b.extreme) - Math.abs(a.extreme));

// Skip coins already alerted on a previous run (static data only persists on active workflows,
// manual test runs always alert).
const store = onlyNew ? $getWorkflowStaticData('global') : null;
const previous = new Set((store && store.lastAlerted) || []);
const selected = onlyNew ? coins.filter((c) => !previous.has(c.coin)) : coins;

const pct = (n) => `${n >= 0 ? '+' : ''}${n.toFixed(3)}%`;
const money = (n) =>
  n >= 1e9 ? `$${(n / 1e9).toFixed(1)}B`
    : n >= 1e6 ? `$${(n / 1e6).toFixed(1)}M`
      : n >= 1e3 ? `$${Math.round(n / 1e3)}K`
        : `$${Math.round(n)}`;

const header = `🔔 Funding rate alert (per funding period)\n` +
  `${selected.length} coin(s) beyond ±${thresholdPct}% · venues with 24h volume ≥ ${money(minVolume)}\n`;

// Telegram rejects messages over 4096 characters: keep whole lines that fit.
const LIMIT = 3900;
let body = '';
const shown = [];
for (const c of selected.slice(0, topN)) {
  const side = c.min > 0 ? 'longs pay shorts' : c.max < 0 ? 'shorts pay longs' : 'opposite signs across venues';
  const range = c.venues > 1 ? `${pct(c.min)} to ${pct(c.max)} on ${c.venues} venues` : `${pct(c.extreme)} on 1 venue`;
  const line = `${c.coin}: ${range} (${side})\n` +
    `   most liquid: ${c.top.market} ${pct(c.top.ratePct)} · 24h vol ${money(c.top.volume)}`;
  const next = body ? `${body}\n\n${line}` : line;
  if (header.length + next.length > LIMIT) break;
  body = next;
  shown.push(c.coin);
}

// Remember what the user has actually seen: coins shown now, plus coins announced earlier that are
// still beyond the threshold. Coins cut from this message stay eligible for the next run.
if (store) {
  const current = new Set(coins.map((c) => c.coin));
  store.lastAlerted = [...[...previous].filter((coin) => current.has(coin)), ...shown];
}

if (shown.length === 0) return [];

const more = selected.length > shown.length ? `\n\n…and ${selected.length - shown.length} more coins` : '';

const response = $('Fetch funding rates from CoinGecko').first().json;
return [{
  json: {
    message: escapeHtml(`${header}\n${body}${more}`),
    count: selected.length,
    contracts_received: contracts.length,
    data_date: (response.headers && response.headers.date) || null,
  },
}];
